      }
      const db = getDb(c.env)
      const stream = sseTrailEventStream(c, db, trailId, cursor)
      return new Response(stream, {
        headers: {
          "content-type": "text/event-stream",
          "cache-control": "no-cache, no-transform",
          "x-accel-buffering": "no",
        },
      })
    }
    const afterParam = c.req.query("after")
    let after: number | undefined
    if (afterParam !== undefined) {
      const parsed = parseSseCursor(afterParam)
      if (parsed === null) {
        return errorEnvelope(
          c,
          400,
          "validation_failed",
          "invalid cursor: after must be a non-negative integer",
          "after",
        )
      }
      after = parsed
    }
    const limit = c.req.query("limit") ? Number(c.req.query("limit")) : 200
    // Must be a non-negative integer — fractional values flow through to
    // Kysely's `.limit(...)` and MySQL rejects them as a server error.
    if (!Number.isInteger(limit) || limit < 0) {
      return errorEnvelope(
        c,
        400,
        "validation_failed",
        "limit must be a non-negative integer",
        "limit",
      )
