export interface SseEventRow {
  id: number
  event_type: string
}

export interface SseStreamConfig<Event extends SseEventRow> {
  readyPayload: Record<string, unknown>
  fetchEvents: (after: number) => Promise<Event[]>
  eventData?: (event: Event) => unknown
  shouldClose?: () => Promise<{ event: string; data: Record<string, unknown> } | null>
  stillAuthorized?: () => Promise<boolean>
  batchSize?: number
  stillAuthorizedIntervalMs?: number
  shouldCloseIntervalMs?: number
}

export const SSE_PING_MS = 15_000
export const SSE_POLL_MS = 1000
export const SSE_MAX_DURATION_MS = 50_000

export function parseSseCursor(raw: string | undefined): number | null {
  if (raw === undefined || raw === "") return 0
  const n = Number(raw)
  if (!Number.isInteger(n) || n < 0 || n > Number.MAX_SAFE_INTEGER) return null
  return n
}

export function eventForWire<E extends { id: number }>(event: E): Omit<E, "id"> & { id: string } {
  const { id, ...rest } = event
  return { ...rest, id: String(id) }
}

export function sseStream<Event extends SseEventRow>(
  request: Request,
  startAfter: number,
  cfg: SseStreamConfig<Event>,
): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder()
  const batchSize = cfg.batchSize ?? 200
  const stillAuthorizedIntervalMs = cfg.stillAuthorizedIntervalMs ?? SSE_POLL_MS
  const shouldCloseIntervalMs = cfg.shouldCloseIntervalMs ?? SSE_POLL_MS
  let cursor = startAfter
  const startedAt = Date.now()
  let closed = false
  let wakeSleep: (() => void) | null = null
  const close = () => {
    closed = true
    wakeSleep?.()
  }
  request.signal.addEventListener("abort", close, { once: true })
  return new ReadableStream<Uint8Array>({
    async start(controller) {
      const finalize = () => {
        close()
        try {
          controller.close()
        } catch {}
      }
      const writeFrame = (event: string, data: unknown, id?: string) => {
        if (closed) return
        const parts: string[] = []
        if (id !== undefined) parts.push(`id: ${id}`)
        parts.push(`event: ${event}`)
        parts.push(`data: ${JSON.stringify(data)}`)
        try {
          controller.enqueue(encoder.encode(`${parts.join("\n")}\n\n`))
        } catch {
          close()
        }
      }
      const drainAndWrite = async (): Promise<{ exhausted: boolean }> => {
        const events = await cfg.fetchEvents(cursor)
        for (const event of events) {
          writeFrame(
            event.event_type,
            cfg.eventData ? cfg.eventData(event) : eventForWire(event),
            String(event.id),
          )
          cursor = event.id
        }
        return { exhausted: events.length < batchSize }
      }
      writeFrame("ready", { ...cfg.readyPayload, cursor })

      let lastPing = Date.now()
      let lastStillAuthorizedAt = 0
      let lastShouldCloseAt = 0
      try {
        while (!closed) {
          const now = Date.now()
          if (now - startedAt > SSE_MAX_DURATION_MS) {
            writeFrame("reconnect", { reason: "max_duration" })
            break
          }
          if (
            cfg.stillAuthorized &&
            (lastStillAuthorizedAt === 0 ||
              now - lastStillAuthorizedAt >= stillAuthorizedIntervalMs)
          ) {
            lastStillAuthorizedAt = now
            const ok = await cfg.stillAuthorized()
            if (!ok) {
              writeFrame("forbidden", { reason: "access_revoked" })
              break
            }
          }
          await drainAndWrite()
          if (closed) break
          if (
            cfg.shouldClose &&
            (lastShouldCloseAt === 0 || Date.now() - lastShouldCloseAt >= shouldCloseIntervalMs)
          ) {
            lastShouldCloseAt = Date.now()
            const closeEvent = await cfg.shouldClose()
            if (closeEvent) {
              let drainHitMaxDuration = false
              while (!closed) {
                if (Date.now() - startedAt > SSE_MAX_DURATION_MS) {
                  writeFrame("reconnect", { reason: "max_duration" })
                  drainHitMaxDuration = true
                  break
                }
                const { exhausted } = await drainAndWrite()
                if (exhausted) break
              }
              if (drainHitMaxDuration) break
              writeFrame(closeEvent.event, closeEvent.data)
              break
            }
          }
          if (Date.now() - lastPing > SSE_PING_MS) {
            controller.enqueue(encoder.encode(`: ping ${Date.now()}\n\n`))
            lastPing = Date.now()
          }
          await interruptibleSleep(SSE_POLL_MS, (wake) => {
            wakeSleep = wake
          })
          wakeSleep = null
        }
      } catch (err) {
        writeFrame("error", { message: err instanceof Error ? err.message : String(err) })
      } finally {
        finalize()
      }
    },
    cancel() {
      close()
    },
  })
}

