    prompt_id: data.prompt_id ?? null,
    sandbox_event_type: data.event_type,
    status: typeof payload.status === "string" ? payload.status : run.status,
  }
}

async function appendTrailRunnerEvent(
  db: Kysely<DB>,
  data: TrailRunnerAppEventInput,
  createdAt: Date,
): Promise<void> {
  await db.transaction().execute(async (tx) => {
    const run = await tx
      .selectFrom("sandbox_runs")
      .select(["id", "automation", "trail_id", "status", "user_id"])
      .where("id", "=", data.run_id)
      .executeTakeFirst()
    if (!run?.trail_id || !run.automation) return
    const trail = await tx
      .selectFrom("repo_trails")
      .select("id")
      .where("id", "=", run.trail_id)
      .executeTakeFirst()
    if (!trail) return
    const payload = buildTrailRunnerEventPayload(run, data)
    if (!payload) return
    await appendTrailEventLog(tx, {
      trailId: run.trail_id,
      actorId: run.user_id ?? "system",
      eventType: `runner.${data.event_type}`,
      targetType: "trail_runner",
      targetId: run.automation,
      payload,
      createdAt,
    })
  })
}

