export async function markPromptFailed(
  db: Db,
  runId: string,
  promptId: string,
  message: string,
  // When the failure is a time-limit kill (reaper or per-prompt timeout), mark
  // the run "timeout" instead of "failed" so the UI/telemetry can distinguish
  // it. The prompt row stays "failed" (its status enum has no timeout).
  options?: { timedOut?: boolean },
): Promise<void> {
  const timedOut = options?.timedOut === true
  await db.sandboxRuns.updatePrompt(promptId, {
    status: "failed",
    error_message: message,
    completed_at: nowIso(),
  })
  await db.sandboxRuns.updateRun(runId, {
    status: timedOut ? "timeout" : "failed",
    error_message: message,
  })
  await db.sandboxRuns.insertAppEvent({
    run_id: runId,
    prompt_id: promptId,
    event_type: "error",
    payload: {
      promptId,
      message,
    },
  })
  recordOutcome(timedOut ? "timeout" : "failed", { "runner.failure_reason": message })
}

