  await db.sandboxRuns.insertAppEvent({
    run_id: runId,
    prompt_id: promptId,
    event_type: "status",
    payload: {
      status: "canceled",
      promptId,
    },
  })
  if (options?.recordOutcome !== false) {
    recordOutcome("canceled")
  }
}

