func trailRunnerID(ev trailStreamEvent) string {
	if runner := payloadString(ev.Payload, "runner_id"); runner != "" {
		return runner
	}
	if ev.TargetID != "" {
		return ev.TargetID
	}
	return "unknown"
}

func trailMonitorValue(payload map[string]any) string {
	valueType := payloadString(payload, "value_type")
	switch valueType {
	case "percent":
		return payloadString(payload, "percent_value")
	case "size":
		return payloadString(payload, "size_value")
	case "boolean":
		return payloadString(payload, "boolean_value")
	}
	for _, key := range []string{"value", "status"} {
		if value := payloadString(payload, key); value != "" {
			return value
		}
	}
	return ""
}

